        self._jobs: list[Job] = []

    def add(self, job: Job) -> None:
        self._jobs.append(job)

    def poll(self) -> Job | None:
        """Removes and returns the best job that is still READY, or None."""
        self._jobs = [j for j in self._jobs if j.status is Status.READY]
        if not self._jobs:
